head.script:
let objParent = $p.parent();



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[common > P > autoFocus]<br/>입력값의 길이가 maxByteLength 값에 도달할때 포커스를 nextTabID 의 컴포넌트로 이동시킬지 여부를 설정합니다.",
    "validation" : [
        "미설정 시 입력값의 Byte 수가 maxByteLength 속성값과 같아져도 포커스를 이동하지 않습니다.",
        "true 설정 시 입력값의 Byte 수가 maxByteLength 속성값과 같아질때 nextTabID 에 설정한 컴포넌트로 포커스를 이동합니다.",
        "false 설정 시 입력값의 Byte 수가 maxByteLength 속성값과 같아져도 포커스를 이동하지 않습니다.",
        "maxByteLength 와 nextTabID 속성값이 설정된 경우 동작합니다.",
        "입력값의 길이가 maxByteLength 값에 도달할때 마지막 문자가 한글인 경우 해당 속성은 false 로 동작합니다.",
        "입력값을 붙여넣기하면 maxByteLength 보다 초과된 길이의 입력값은 제거된 후 포커스가 이동합니다.",
        "입력값을 붙여넣기 시 남아 있는 입력값의 마지막 문자가 한글이면 autofocus 속성은 false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};




// comp 재생성
scwin.comp_init = function () {
    // comp 생성 호출
    objParent.scwin.comp_init();
};



scwin.btn_getText_onclick = function (e) {
    let rtn = '';
    let tagName = objParent.target1.render.tagName

    if (tagName !== "INPUT") {
        rtn = objParent.target1.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = objParent.target1.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



// 테스트 샘플의 이벤트 처리
objParent.scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onblur 이벤트 발생=====");    
}


// 테스트 샘플의 이벤트 처리
objParent.scwin.input2_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====input2_onfocus 이벤트 발생=====");    
}
